composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      YOURLS_DB_HOST: "{{serviceName}}-mysql"
      YOURLS_DB_NAME: yourls
      YOURLS_DB_USER: yourls
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      YOURLS_SITE: {{env.YOURLS_SITE}}
      YOURLS_USER: {{env.YOURLS_USER}}
      YOURLS_PASS: {{env.YOURLS_PASS}}
    volumes:
      - {{appDataPath}}/html:/var/www/html
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: yourls
      MYSQL_USER: yourls
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
